/**
 * Configures the mapping between two bean types.
 * <p>
 * Unless otherwise specified these properties are inherited to the generated bean mapping methods.
 * <p>
 * Either {@link #resultType()}, {@link #qualifiedBy()} or {@link #nullValueMappingStrategy()} must be specified.
 * </p>
 * <p><strong>Example:</strong> Determining the result type</p>
 * <pre><code class='java'>
 * // When result types have an inheritance relation, selecting either mapping method {@link Mapping} or factory method
 * // {@link BeanMapping} can be become ambiguous. Parameter  {@link BeanMapping#resultType()} can be used.
 * public class FruitFactory {
 *     public Apple createApple() {
 *         return new Apple();
 *     }
 *     public Orange createOrange() {
 *         return new Orange();
 *     }
 * }
 * &#64;Mapper(uses = FruitFactory.class)
 * public interface FruitMapper {
 *     &#64;BeanMapping(resultType = Apple.class)
 *     Fruit toFruit(FruitDto fruitDto);
 * }
 * </code></pre>
 * <pre><code class='java'>
 * // generates
 * public class FruitMapperImpl implements FruitMapper {
 *      &#64;Override
 *      public Fruit toFruit(FruitDto fruitDto) {
 *          Apple fruit = fruitFactory.createApple();
 *          // ...
 *      }
 * }
 * </code></pre>
 *
 * @author Sjaak Derksen
 */
@Target(ElementType.METHOD)
@Retention(RetentionPolicy.CLASS)
public @interface BeanMapping {

    /**
     * Specifies the result type of the factory method to be used in case several factory methods qualify.
     * <p>
     * <b>NOTE</b>: This property is not inherited to generated mapping methods
     *
     * @return the resultType to select
     */
    Class<?> resultType() default void.class;

    /**
     * A qualifier can be specified to aid the selection process of a suitable factory method or filtering applicable
     * {@code @}{@link BeforeMapping} / {@code @}{@link AfterMapping} methods. This is useful in case multiple factory
     * method (hand written of internal) qualify and result in an 'Ambiguous factory methods' error.
     * <p>
     * A qualifier is a custom annotation and can be placed on either a hand written mapper class or a method.
     *
     * @return the qualifiers
     * @see Qualifier
     */
    Class<? extends Annotation>[] qualifiedBy() default {};

    /**
     * Similar to {@link #qualifiedBy()}, but used in combination with {@code @}{@link Named} in case no custom
     * qualifier annotation is defined.
     *
     * @return the qualifiers
     * @see Named
     */
    String[] qualifiedByName() default { };

    /**
     * The strategy to be applied when {@code null} is passed as source bean argument value to this bean mapping. If no
     * strategy is configured, the strategy given via {@link MapperConfig#nullValueMappingStrategy()} or
     * {@link Mapper#nullValueMappingStrategy()} will be applied, using {@link NullValueMappingStrategy#RETURN_NULL}
     * by default.
     *
     * @return The strategy to be applied when {@code null} is passed as source value to the methods of this mapping.
     */
    NullValueMappingStrategy nullValueMappingStrategy() default NullValueMappingStrategy.RETURN_NULL;

    /**
     * The strategy to be applied when a source bean property is {@code null} or not present. If no strategy is
     * configured, the strategy given via {@link MapperConfig#nullValuePropertyMappingStrategy()} or
     * {@link Mapper#nullValuePropertyMappingStrategy()} will be applied,
     * {@link NullValuePropertyMappingStrategy#SET_TO_NULL} will be used by default.
     *
     * @since 1.3
     *
     * @return The strategy to be applied when {@code null} is passed as source property value or the source property
     * is not present.
     */
    NullValuePropertyMappingStrategy nullValuePropertyMappingStrategy()
        default NullValuePropertyMappingStrategy.SET_TO_NULL;

    /**
     * Determines when to include a null check on the source property value of a bean mapping.
     *
     * Can be overridden by the one on {@link MapperConfig}, {@link Mapper}  or {@link Mapping}.
     *
     * @return strategy how to do null checking
     */
    NullValueCheckStrategy nullValueCheckStrategy() default ON_IMPLICIT_CONVERSION;

    /**
     * Determines how to handle missing implementation for super classes when using the {@link SubclassMapping}.
     *
     * Overrides the setting on {@link MapperConfig} and {@link Mapper}.
     *
     * @return strategy to handle missing implementation combined with {@link SubclassMappings}.
     *
     * @since 1.5
     */
    SubclassExhaustiveStrategy subclassExhaustiveStrategy() default COMPILE_ERROR;

    /**
     * Specifies the exception type to be thrown when a missing subclass implementation is detected
     * in combination with {@link SubclassMappings}, based on the {@link #subclassExhaustiveStrategy()}.
     * <p>
     * This exception will only be thrown when the {@code subclassExhaustiveStrategy} is set to
     * {@link SubclassExhaustiveStrategy#RUNTIME_EXCEPTION}.
     *
     * @return the exception class to throw when missing implementations are found.
     *         Defaults to {@link IllegalArgumentException}.
     */
    Class<? extends Exception> subclassExhaustiveException() default IllegalArgumentException.class;

    /**
     * Default ignore all mappings. All mappings have to be defined manually. No automatic mapping will take place. No
     * warning will be issued on missing source or target properties.
     *
     * @return The ignore strategy (default false).
     *
     * @since 1.3
     */
    boolean ignoreByDefault() default false;

    /**
     * Unmapped source properties to be ignored. This could be used when {@link ReportingPolicy#WARN}
     * or {@link ReportingPolicy#ERROR} is used for {@link Mapper#unmappedSourcePolicy()} or
     * {@link MapperConfig#unmappedSourcePolicy()}. Listed properties will be ignored when composing the unmapped
     * source properties report.
     * <p>
     * <b>NOTE</b>: This does not support ignoring nested source properties
     * <p>
     * <b>NOTE</b>: This property is not inherited to generated mapping methods
     *
     * @return The source properties that should be ignored when performing a report
     *
     * @since 1.3
     */
    String[] ignoreUnmappedSourceProperties() default {};

    /**
     * How unmapped properties of the source type of a mapping should be reported.
     * If no policy is configured, the policy given via {@link MapperConfig#unmappedSourcePolicy()} or
     * {@link Mapper#unmappedSourcePolicy()} will be applied, using {@link ReportingPolicy#IGNORE} by default.
     *
     * @return The reporting policy for unmapped source properties.
     *
     * @since 1.6
     */
    ReportingPolicy unmappedSourcePolicy() default ReportingPolicy.IGNORE;

    /**
     * How unmapped properties of the target type of a mapping should be reported.
     * If no policy is configured, the policy given via {@link MapperConfig#unmappedTargetPolicy()} or
     * {@link Mapper#unmappedTargetPolicy()} will be applied, using {@link ReportingPolicy#WARN} by default.
     *
     * @return The reporting policy for unmapped target properties.
     *
     * @since 1.5
     */
    ReportingPolicy unmappedTargetPolicy() default ReportingPolicy.WARN;

    /**
     * The information that should be used for the builder mappings. This can be used to define custom build methods
     * for the builder strategy that one uses.
     *
     * If no builder is defined the builder given via {@link MapperConfig#builder()} or {@link Mapper#builder()}
     * will be applied.
     * <p>
     * NOTE: In case no builder is defined here, in {@link Mapper} or {@link MapperConfig} and there is a single
     * build method, then that method would be used.
     * <p>
     * If the builder is defined and there is a single method that does not match the name of the finisher than
     * a compile error will occurs
     *
     * @return the builder information for the method level
     *
     * @since 1.3
     */
    Builder builder() default @Builder;

    /**
     * Allows detailed control over the mapping process.
     *
     * @return the mapping control
     *
     * @since 1.4
     *
     * @see org.mapstruct.control.DeepClone
     * @see org.mapstruct.control.NoComplexMapping
     * @see org.mapstruct.control.MappingControl
     */
    Class<? extends Annotation> mappingControl() default MappingControl.class;

}
        }
        // otherwise add reference to existing mapper method
        else if ( isValidReferencedMethod( parameters ) || isValidFactoryMethod( method, parameters, returnType )
            || isValidLifecycleCallbackMethod( method )
            || isValidPresenceCheckMethod( method, parameters, returnType ) ) {
            return getReferencedMethod( usedMapper, methodType, method, mapperToImplement, parameters );
        }
        else {
            return null;
        }
    }

    private SourceMethod getMethodRequiringImplementation(ExecutableType methodType, ExecutableElement method,
            List<Parameter> parameters,
            boolean containsTargetTypeParameter,
            MapperOptions mapperOptions,
            List<SourceMethod> prototypeMethods,
            TypeElement mapperToImplement) {
        Type returnType = typeFactory.getReturnType( methodType );
        List<Type> exceptionTypes = typeFactory.getThrownTypes( methodType );
        List<Parameter> sourceParameters = Parameter.getSourceParameters( parameters );
        List<Parameter> contextParameters = Parameter.getContextParameters( parameters );
        Parameter targetParameter = extractTargetParameter( parameters );
        Type resultType = selectResultType( returnType, targetParameter );

        boolean isValid = checkParameterAndReturnType(
            method,
            sourceParameters,
            targetParameter,
            contextParameters,
            resultType,
            returnType,
            containsTargetTypeParameter
        );

        if ( !isValid ) {
            return null;
        }

        ParameterProvidedMethods contextProvidedMethods =
            retrieveContextProvidedMethods( contextParameters, mapperToImplement, mapperOptions );

        BeanMappingOptions beanMappingOptions = BeanMappingOptions.getInstanceOn(
            BeanMappingGem.instanceOn( method ),
            mapperOptions,
            method,
            messager,
            typeUtils,
            typeFactory );

        Set<MappingOptions> mappingOptions = getMappings( method, beanMappingOptions );

        IterableMappingOptions iterableMappingOptions = IterableMappingOptions.fromGem(
            IterableMappingGem.instanceOn( method ),
            mapperOptions,
            method,
            messager,
            typeUtils
        );

        MapMappingOptions mapMappingOptions = MapMappingOptions.fromGem(
            MapMappingGem.instanceOn( method ),
            mapperOptions,
            method,
            messager,
            typeUtils
        );

        EnumMappingOptions enumMappingOptions = EnumMappingOptions.getInstanceOn(
            method,
            mapperOptions,
            enumTransformationStrategies,
            messager
        );

        // We want to get as much error reporting as possible.
        // If targetParameter is not null it means we have an update method
        SubclassValidator subclassValidator = new SubclassValidator( messager, typeUtils );
        Set<SubclassMappingOptions> subclassMappingOptions = getSubclassMappings(
            sourceParameters,
            targetParameter != null ? null : resultType,
            method,
            beanMappingOptions,
            subclassValidator
        );

        return new SourceMethod.Builder()
            .setExecutable( method )
            .setParameters( parameters )
            .setReturnType( returnType )
            .setExceptionTypes( exceptionTypes )
            .setMapper( mapperOptions )
            .setBeanMappingOptions( beanMappingOptions )
            .setMappingOptions( mappingOptions )
            .setIterableMappingOptions( iterableMappingOptions )
            .setMapMappingOptions( mapMappingOptions )
            .setValueMappingOptionss( getValueMappings( method ) )
            .setEnumMappingOptions( enumMappingOptions )
            .setSubclassMappings( subclassMappingOptions )
            .setSubclassValidator( subclassValidator )
            .setTypeUtils( typeUtils )
            .setTypeFactory( typeFactory )
            .setPrototypeMethods( prototypeMethods )
            .setContextProvidedMethods( contextProvidedMethods )
            .setVerboseLogging( options.isVerbose() )
            .build();
    }

    private ParameterProvidedMethods retrieveContextProvidedMethods(
            List<Parameter> contextParameters, TypeElement mapperToImplement, MapperOptions mapperConfig) {

        ParameterProvidedMethods.Builder builder = ParameterProvidedMethods.builder();
        for ( Parameter contextParam : contextParameters ) {
            if ( contextParam.getType().isPrimitive() || contextParam.getType().isArrayType() ) {
                continue;
            }
            List<SourceMethod> contextParamMethods = retrieveMethods(
                contextParam.getType(),
                mapperToImplement,
                mapperConfig,
                Collections.emptyList() );

            List<SourceMethod> contextProvidedMethods = new ArrayList<>( contextParamMethods.size() );
            for ( SourceMethod sourceMethod : contextParamMethods ) {
                if ( sourceMethod.isLifecycleCallbackMethod() || sourceMethod.isObjectFactory()
                    || sourceMethod.getConditionOptions().isAnyStrategyApplicable() ) {
                    contextProvidedMethods.add( sourceMethod );
                }
            }

            builder.addMethodsForParameter( contextParam, contextProvidedMethods );
            return false;
        }

        return true;
    }

    private boolean isStreamTypeOrIterableFromJavaStdLib(Type type) {
        return type.isStreamType() || ( type.isIterableType() && type.isJavaLangType() );
    }

    /**
     * Retrieves the mappings configured via {@code @Mapping} from the given method.
     *
     * @param method The method of interest
     * @param beanMapping options coming from bean mapping method
     * @return The mappings for the given method, keyed by target property name
     */
    private Set<MappingOptions> getMappings(ExecutableElement method, BeanMappingOptions beanMapping) {
        Set<MappingOptions> processedAnnotations = new RepeatableMappings( beanMapping )
                .getProcessedAnnotations( method );
        processedAnnotations.addAll( new IgnoredConditions( processedAnnotations )
                .getProcessedAnnotations( method ) );
        return processedAnnotations;
    }

    /**
     * Retrieves the subclass mappings configured via {@code @SubclassMapping} from the given method.
     *
     * @param method The method of interest
     * @param beanMapping options coming from bean mapping method
     *
     * @return The subclass mappings for the given method
     */
    private Set<SubclassMappingOptions> getSubclassMappings(List<Parameter> sourceParameters, Type resultType,
                                                            ExecutableElement method, BeanMappingOptions beanMapping,
                                                            SubclassValidator validator) {
        return new RepeatableSubclassMappings( beanMapping, sourceParameters, resultType, validator )
                        .getProcessedAnnotations( method );
    }

    /**
     * Retrieves the conditions configured via {@code @Condition} from the given method.
     *
     * @param method     The method of interest
     * @param parameters
     * @return The condition options for the given method
     */

    private Set<ConditionOptions> getConditionOptions(ExecutableElement method, List<Parameter> parameters) {
        return new MetaConditions( parameters ).getProcessedAnnotations( method );
    }

    private class RepeatableMappings extends RepeatableAnnotations<MappingGem, MappingsGem, MappingOptions> {
        private BeanMappingOptions beanMappingOptions;

        RepeatableMappings(BeanMappingOptions beanMappingOptions) {
            super( elementUtils, MAPPING_FQN, MAPPINGS_FQN );
            this.beanMappingOptions = beanMappingOptions;
        }

        @Override
        protected MappingGem singularInstanceOn(Element element) {
            return MappingGem.instanceOn( element );
        }

        @Override
        protected MappingsGem multipleInstanceOn(Element element) {
            return MappingsGem.instanceOn( element );
        }

        @Override
        protected void addInstance(MappingGem gem, Element method, Set<MappingOptions> mappings) {
            MappingOptions.addInstance(
                                       gem,
                                       (ExecutableElement) method,
                                       beanMappingOptions,
                                       messager,
                                       typeUtils,
                                       mappings );
        }

        @Override
        protected void addInstances(MappingsGem gem, Element method, Set<MappingOptions> mappings) {
            MappingOptions.addInstances(
                                        gem,
                                        (ExecutableElement) method,
                                        beanMappingOptions,
                                        messager,
                                        typeUtils,
                                        mappings );
        }
    }

    private class RepeatableSubclassMappings
        extends RepeatableAnnotations<SubclassMappingGem, SubclassMappingsGem, SubclassMappingOptions> {
        private final List<Parameter> sourceParameters;
        private final Type resultType;
        private SubclassValidator validator;
        private BeanMappingOptions beanMappingOptions;

        RepeatableSubclassMappings(BeanMappingOptions beanMappingOptions, List<Parameter> sourceParameters,
                                   Type resultType, SubclassValidator validator) {
            super( elementUtils, SUB_CLASS_MAPPING_FQN, SUB_CLASS_MAPPINGS_FQN );
            this.beanMappingOptions = beanMappingOptions;
            this.sourceParameters = sourceParameters;
            this.resultType = resultType;
