/*
 * Copyright MapStruct Authors.
 *
 * Licensed under the Apache License version 2.0, available at http://www.apache.org/licenses/LICENSE-2.0
 */
package org.mapstruct.ap.test.inheritsupermappings;

import javax.tools.Diagnostic.Kind;

import org.mapstruct.ap.testutil.ProcessorTest;
import org.mapstruct.ap.testutil.WithClasses;
import org.mapstruct.ap.testutil.compilation.annotation.CompilationResult;
import org.mapstruct.ap.testutil.compilation.annotation.Diagnostic;
import org.mapstruct.ap.testutil.compilation.annotation.ExpectedCompilationOutcome;

import static org.assertj.core.api.Assertions.assertThat;

public class InheritSuperMappingsTest {

    @ProcessorTest
    @WithClasses(SuperMappingsMapper.class)
    public void shouldInheritSuperMappings() {
        Source first = source( "first", "second", "branch", "automatic", "base", "mid" );
        Source second = source( "otherFirst", "otherSecond", "otherBranch", "otherAutomatic", "otherBase", "otherMid" );

        Target mapped = SuperMappingsMapper.INSTANCE.map( first, second );

        assertThat( mapped.getFirstOut() ).isEqualTo( "otherFirst" );
        assertThat( mapped.getSecondOut() ).isEqualTo( "otherSecond" );
        assertThat( mapped.getBranchOut() ).isEqualTo( "branch" );
    }

    @ProcessorTest
    @WithClasses(SuperMappingsMapper.class)
    public void shouldNotInheritOtherBeanMappingOptions() {
        Source source = source( "first", "second", "branch", "automatic", "base", "mid" );

        Target mapped = SuperMappingsMapper.INSTANCE.automatic( source );

        assertThat( mapped.getFirstOut() ).isEqualTo( "first" );
        assertThat( mapped.getAutomatic() ).isEqualTo( "automatic" );
    }

    @ProcessorTest
    @WithClasses(SuperMappingsMapper.class)
    public void shouldAcceptOverriddenMappingMethodWithoutMappings() {
        Source source = source( "first", "second", "branch", "automatic", "base", "mid" );

        Target mapped = SuperMappingsMapper.INSTANCE.empty( source );

        assertThat( mapped.getAutomatic() ).isEqualTo( "automatic" );
    }

    @ProcessorTest
    @WithClasses(SuperMappingsMapper.class)
    public void shouldPreservePropertyAndRebindWholeParameterSources() {
        PropertySource propertySource = new PropertySource();
        propertySource.setSource( "property" );
        WholeSource wholeSource = new WholeSource();
        wholeSource.setValue( "whole" );

        PropertyTarget propertyTarget = SuperMappingsMapper.INSTANCE.property( propertySource );
        WholeTarget wholeTarget = SuperMappingsMapper.INSTANCE.whole( wholeSource );

        assertThat( propertyTarget.getValue() ).isEqualTo( "property" );
        assertThat( wholeTarget.getNested() ).isSameAs( wholeSource );
    }

    @ProcessorTest
    @WithClasses(SuperMappingsMapper.class)
    public void shouldAccumulateFlatteningMappings() {
        FlattenLeft left = new FlattenLeft();
        left.setLeftValue( "left" );
        FlattenRight right = new FlattenRight();
        right.setRightValue( "right" );

        FlattenTarget target = SuperMappingsMapper.INSTANCE.flatten( left, right );

        assertThat( target.getLeftValue() ).isEqualTo( "left" );
        assertThat( target.getRightValue() ).isEqualTo( "right" );
    }

    @ProcessorTest
    @WithClasses(SuperMappingsMapper.class)
    public void shouldPreferMostSpecificInheritedMapping() {
        Source source = source( "first", "second", "branch", "automatic", "base", "mid" );

        Target target = SuperMappingsMapper.INSTANCE.mostSpecific( source );

        assertThat( target.getWinner() ).isEqualTo( "mid" );
    }

    @ProcessorTest
    @WithClasses({ ErroneousNoOverrideMapper.class, Source.class, Target.class })
    @ExpectedCompilationOutcome(
        value = CompilationResult.FAILED,
        diagnostics = @Diagnostic(
            type = ErroneousNoOverrideMapper.class,
            kind = Kind.ERROR,
            line = 15,
            message = "@BeanMapping(inheritSuperMappings = true) requires the method to override a mapping method."
        )
    )
    public void shouldRejectMethodWithoutOverride() {
    }

    @ProcessorTest
    @WithClasses({ ErroneousConflictMapper.class, Source.class, Target.class })
    @ExpectedCompilationOutcome(
        value = CompilationResult.FAILED,
        diagnostics = @Diagnostic(
            type = ErroneousConflictMapper.class,
            kind = Kind.ERROR,
            line = 16,
            message = "Inherited mappings for target property \"winner\" are declared in incomparable mapper types "
                + "org.mapstruct.ap.test.inheritsupermappings.LeftConflictMapper and "
                + "org.mapstruct.ap.test.inheritsupermappings.RightConflictMapper."
        )
    )
    public void shouldRejectConflictingBranches() {
    }

    private Source source(String first, String second, String branch, String automatic, String baseValue,
                          String midValue) {
        Source source = new Source();
        source.setFirst( first );
        source.setSecond( second );
        source.setBranch( branch );
        source.setAutomatic( automatic );
        source.setBaseValue( baseValue );
        source.setMidValue( midValue );
        return source;
    }
}
