   509	    private Integer sourceParameterPosition(String sourceName, List<Parameter> parameters) {
   510	        if ( sourceName == null ) {
   511	            return null;
   512	        }
   513	        String[] segments = sourceName.trim().split( "\\." );
   514	        List<Parameter> sourceParameters = Parameter.getSourceParameters( parameters );
   515	        if ( sourceParameters.isEmpty() ) {
   516	            return null;
   517	        }
   518	        if ( sourceParameters.size() > 1 ) {
   519	            return parameterPosition( parameters, Parameter.getSourceParameter( parameters, segments[0] ) );
   520	        }
   521	
   522	        Parameter sourceParameter = sourceParameters.get( 0 );
   523	        if ( matchesPropertyPath( sourceParameter, segments ) ) {
   524	            return null;
   525	        }
   526	        if ( sourceParameter.getName().equals( segments[0] ) ) {
   527	            return parameterPosition( parameters, sourceParameter );
   528	        }
   529	        return null;
   530	    }
