   532	    private boolean matchesPropertyPath(Parameter parameter, String[] propertyNames) {
   533	        Type propertyType = parameter.getType();
   534	        boolean allowedMapToBean = !propertyType.isMapType() || !propertyNames[0].equals( parameter.getName() );
   535	        for ( int i = 0; i < propertyNames.length; i++ ) {
   536	            Type noBoundsType = propertyType.withoutBounds();
   537	            if ( noBoundsType.isOptionalType() ) {
   538	                noBoundsType = noBoundsType.getOptionalBaseType();
   539	            }
   540	            ReadAccessor readAccessor = noBoundsType.getReadAccessor( propertyNames[i], i > 0 || allowedMapToBean );
   541	            if ( readAccessor == null ) {
   542	                return false;
   543	            }
   544	            propertyType = typeFactory.getReturnType( (DeclaredType) noBoundsType.getTypeMirror(), readAccessor );
   545	        }
   546	        return true;
   547	    }
   548	
   549	    private Integer parameterPosition(List<Parameter> parameters, Parameter parameter) {
   550	        return parameter == null ? null : parameters.indexOf( parameter );
   551	    }
